const CFG = __MON_CONFIG__;
const sd = $getWorkflowStaticData('global');
sd.vistos = sd.vistos || {};
const norm = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();

const nomes = [CFG.nome].concat(CFG.variacoes || []).map(s => String(s || '').trim()).filter(Boolean).slice(0, 3);
if (nomes.length === 0) throw new Error('Nenhum nome configurado. Rode: bash instalar_monitor_privacidade.sh --reconfigurar');
const desde = new Date(Date.now() - 7 * 86400000).toISOString().slice(0, 10);
const enc = encodeURIComponent;
const itens = [];
nomes.forEach(n => {
  const frase = '"' + n + '"';
  // municipal e federal passam pelo agente do Mac (o n8n no Docker falhou no TLS com o Querido Diário); o agente só busca sites permitidos
  const viaAgente = u => 'http://host.docker.internal:8003/web/get?u=' + enc(u);
  itens.push({ json: { fonte: 'municipal', nome: n, agente: true, url: viaAgente('https://api.queridodiario.ok.org.br/gazettes?territory_ids=3550308&querystring=' + enc(frase) + '&published_since=' + desde + '&size=10&excerpt_size=300&number_of_excerpts=2&sort_by=descending_date') } });
  itens.push({ json: { fonte: 'federal', nome: n, agente: true, url: viaAgente('https://www.in.gov.br/consulta/-/buscar/dou?q=' + enc(frase) + '&s=todos&exactDate=semana&sortType=0') } });
  itens.push({ json: { fonte: 'estadual', nome: n, url: 'http://searxng:8080/search?format=json&safesearch=0&language=pt-BR&categories=general&time_range=month&q=' + enc(frase + ' (site:doe.sp.gov.br OR site:imprensaoficial.com.br)') } });
});
return itens;

const CFG = __MON_CONFIG__;
const sd = $getWorkflowStaticData('global');
sd.vistos = sd.vistos || {};
const norm = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();

const consultas = $('Consultas').all();
const resp = $input.all();
const ROT = { municipal: 'Município de São Paulo (Querido Diário)', federal: 'Diário Oficial da União', estadual: 'Diário Oficial do Estado de SP (busca indireta, cobertura parcial)' };
const fontes = { municipal: { ok: 0, falha: 0, motivo: '' }, federal: { ok: 0, falha: 0, motivo: '' }, estadual: { ok: 0, falha: 0, motivo: '' } };
const achados = { municipal: [], federal: [], estadual: [] };
const agora = Date.now();
Object.keys(sd.vistos).forEach(k => { if (agora - ((sd.vistos[k] || {}).t || 0) > 120 * 86400000) delete sd.vistos[k]; });
const falhou = (f, m) => { fontes[f].falha++; if (!fontes[f].motivo) fontes[f].motivo = m; };
resp.forEach((r, i) => {
  const c = (consultas[i] || { json: {} }).json;
  const f = c.fonte;
  if (!fontes[f]) return;
  const j = r.json || {};
  if (j.error) { falhou(f, 'sem resposta (' + String((j.error.message || j.error)).slice(0, 80) + ')'); return; }
  let lista = [];
  try {
    if (f === 'municipal') {
      const d = JSON.parse(j.data);
      if (!Array.isArray(d.gazettes)) throw new Error('formato inesperado');
      lista = d.gazettes.map(g => ({ titulo: (g.territory_name || 'São Paulo') + ' - edição de ' + g.date + (g.edition ? ' (nº ' + g.edition + ')' : ''), data: g.date, url: g.url, trecho: (g.excerpts || []).join(' ... ').replace(/\s+/g, ' ').slice(0, 500) }));
    } else if (f === 'federal') {
      const m = /<script[^>]*id="_br_com_seatecnologia_in_buscadou_BuscaDouPortlet_params"[^>]*>([\s\S]*?)<\/script>/.exec(String(j.data || ''));
      if (!m) throw new Error('a página do DOU mudou de formato ou bloqueou o acesso');
      const d = JSON.parse(m[1]);
      const arr = d.jsonArray || d.results;
      if (!Array.isArray(arr)) throw new Error('lista de resultados não encontrada');
      lista = arr.map(x => ({ titulo: String(x.title || x.pubName || 'Publicação do DOU').replace(/<[^>]+>/g, '').slice(0, 200), data: x.pubDate || '', url: x.urlTitle ? 'https://www.in.gov.br/web/dou/-/' + x.urlTitle : '', trecho: String(x.content || x.abstract || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').slice(0, 500) }));
    } else {
      const d = JSON.parse(typeof j.data === 'string' ? j.data : JSON.stringify(j));
      if (!Array.isArray(d.results)) throw new Error('formato inesperado');
      lista = d.results.filter(x => /doe\.sp\.gov\.br|imprensaoficial\.com\.br/i.test(String(x.url || ''))).map(x => ({ titulo: String(x.title || '').slice(0, 200), data: '', url: x.url, trecho: String(x.content || '').slice(0, 500) }));
    }
  } catch (e) { falhou(f, String(e.message).slice(0, 100)); return; }
  fontes[f].ok++;
  lista.slice(0, 10).forEach(x => {
    if (!x.url) return;
    const chave = f + '|' + String(x.url).toLowerCase();
    if (sd.vistos[chave]) return;
    sd.vistos[chave] = { t: agora };
    achados[f].push(Object.assign({ nome: c.nome }, x));
  });
});
const falhas = Object.keys(fontes).filter(f => fontes[f].falha > 0);
const todasFalharam = Object.keys(fontes).every(f => fontes[f].ok === 0);
if (todasFalharam) throw new Error('Nenhum diário oficial respondeu. ' + falhas.map(f => ROT[f] + ': ' + fontes[f].motivo).join('; '));
const total = Object.keys(achados).reduce((s, f) => s + achados[f].length, 0);
const avisoFalha = falhas.length ? 'Atenção: ' + falhas.map(f => ROT[f] + ' não pôde ser consultado (' + fontes[f].motivo + ')').join('; ') + '. Isso não quer dizer que não haja nada nessas fontes. ' : '';
if (total === 0) {
  return [{ json: { vazio: true, titulo: falhas.length ? 'Diários oficiais: consulta incompleta' : 'Diários oficiais: nada novo', corpo: avisoFalha + (falhas.length ? 'Nas demais fontes, nada novo com o seu nome.' : 'Nenhuma menção nova ao seu nome nos diários federal, estadual e municipal.') } }];
}
const hoje = new Date().toISOString().slice(0, 10);
let md = '# Diários oficiais - ' + hoje + '\n\n' + (avisoFalha ? avisoFalha + '\n\n' : '') + 'Menções novas ao seu nome. Confira o documento antes de concluir qualquer coisa: pode haver homônimo. Nunca clique em links recebidos por e-mail ou mensagem sobre isso; abra os sites oficiais por conta própria.\n\n';
Object.keys(achados).forEach(f => {
  if (!achados[f].length) return;
  md += '## ' + ROT[f] + '\n\n';
  achados[f].forEach((x, k) => { md += (k + 1) + '. ' + x.titulo + (x.data ? ' - ' + x.data : '') + '\n   Nome pesquisado: ' + x.nome + '\n   Trecho: ' + (x.trecho || '(sem trecho)') + '\n   Link: ' + x.url + '\n\n'; });
});
const resumo = Object.keys(achados).filter(f => achados[f].length).map(f => achados[f].length + ' no ' + (f === 'federal' ? 'federal' : f === 'estadual' ? 'estadual' : 'municipal')).join(', ');
return [{ json: { vazio: false, titulo: 'Diários oficiais ' + hoje, markdown: md, tituloBark: 'Diários oficiais: ' + total + ' menção(ões) nova(s)', bark: resumo + '. ' + avisoFalha + 'Leia o resumo na pasta Monitor de Privacidade do Notas.' } }];
